require"action_dispatch/middleware/session/abstract_store";module ActionDispatch;module Session;class CacheStore<AbstractSecureStore;def initialize(app,options={})@cache=options[:cache]||Rails.cache;options[:expire_after]||=@cache.options[:expires_in];super ;end;def find_session(env,sid)unless sid&&(session=get_session_with_fallback(sid));sid,session=generate_sid,{};end;[sid,session];end;def write_session(env,sid,session,options)key=cache_key(sid.private_id);if session;@cache.write(key,session,expires_in:options[:expire_after]);else @cache.delete(key);end;sid;end;def delete_session(env,sid,options)@cache.delete(cache_key(sid.private_id));@cache.delete(cache_key(sid.public_id));generate_sid;end;private;def cache_key(id)"_session_id:#{id}";end;def get_session_with_fallback(sid)@cache.read(cache_key(sid.private_id))||@cache.read(cache_key(sid.public_id));end;end;end;end
